operations.reducer:
if (action.input.name !== undefined) state.name = action.input.name;
if (action.input.institution !== undefined) state.institution = action.input.institution;
if (action.input.iban !== undefined) state.iban = action.input.iban;
if (action.input.kind !== undefined && action.input.kind !== null) state.kind = action.input.kind;
if (action.input.currency !== undefined && action.input.currency !== null) {
  if (state.transactions.length > 0 && action.input.currency !== state.currency) {
    throw new CurrencyLockedError("The currency cannot change once transactions exist");
  }
  state.currency = action.input.currency;
}
if (action.input.openingBalance !== undefined && action.input.openingBalance !== null) state.openingBalance = action.input.openingBalance;

operations.schema:
input ImportTransactionsInput {
  batchId: String!
  importedAt: DateTime!
  transactions: [ImportedTransactionInput!]!
}

input ImportedTransactionInput {
  id: OID!
  bookedAt: DateTime!
  amount: Float!
  counterparty: String!
  description: String
  reference: String
}

operations.reducer:
if (action.input.transactions.length === 0) throw new EmptyImportError("Nothing to import");
const known = new Set(state.transactions.map((t) => t.reference).filter((r) => r !== null));
for (const t of action.input.transactions) {
  if (t.reference && known.has(t.reference)) {
    throw new DuplicateTransactionError(`Transaction ${t.reference} was imported before`);
  }
  if (t.reference) known.add(t.reference);
  state.transactions.push({
    id: t.id,
    bookedAt: t.bookedAt,
    amount: t.amount,
    counterparty: t.counterparty,
    description: t.description || null,
    reference: t.reference || null,
    category: "UNCATEGORIZED",
    contactId: null,
    matchedDocumentId: null,
    matchedKind: null,
    status: "NEW",
    importBatch: action.input.batchId,
  });
}
state.lastImportedAt = action.input.importedAt;

operations.schema:
input CategorizeTransactionInput {
  id: OID!
  category: TransactionCategory!
  contactId: String
}

operations.reducer:
const tx = state.transactions.find((t) => t.id === action.input.id);
if (!tx) throw new TransactionNotFoundError(`Transaction ${action.input.id} not found`);
tx.category = action.input.category;
if (action.input.contactId !== undefined) tx.contactId = action.input.contactId;
if (tx.status === "NEW") tx.status = "CATEGORIZED";

operations.schema:
input MatchTransactionInput {
  id: OID!
  documentId: String!
  kind: MatchKind!
}

operations.reducer:
const tx = state.transactions.find((t) => t.id === action.input.id);
if (!tx) throw new TransactionNotFoundError(`Transaction ${action.input.id} not found`);
if (tx.status === "EXCLUDED") throw new TransactionExcludedError("An excluded transaction cannot be matched");
tx.matchedDocumentId = action.input.documentId;
tx.matchedKind = action.input.kind;
tx.status = "MATCHED";

const tx = state.transactions.find((t) => t.id === action.input.id);
if (!tx) throw new TransactionNotFoundError(`Transaction ${action.input.id} not found`);
tx.matchedDocumentId = null;
tx.matchedKind = null;
tx.status = tx.category === "UNCATEGORIZED" ? "NEW" : "CATEGORIZED";

operations.schema:
input ExcludeTransactionInput {
  id: OID!
  excluded: Boolean!
}

operations.reducer:
const tx = state.transactions.find((t) => t.id === action.input.id);
if (!tx) throw new TransactionNotFoundError(`Transaction ${action.input.id} not found`);
if (action.input.excluded) {
  tx.matchedDocumentId = null;
  tx.matchedKind = null;
  tx.status = "EXCLUDED";
} else {
  tx.status = tx.category === "UNCATEGORIZED" ? "NEW" : "CATEGORIZED";
}
